class Solution {
  public List<String> partitionString(String s) {
    java.util.HashSet<String> seen = new java.util.HashSet<>();
    List<String> res = new ArrayList<>();
    int start = 0;
    for (int i = 0; i < s.length(); i++) {
      String cur = s.substring(start, i + 1);
      if (seen.add(cur)) {
        res.add(cur);
        start = i + 1;
      }
    }
    return res;
  }
}
